# Sounds to be used with SimonSays Game
# Two sounds provided:
# call moo
# call scream
# Andreas Moshovos 2024

	.text
	.align	2
	.globl	audio_playback_mono
audio_playback_mono:
	li	a5,-14667776
	li	a4,8
	sw	a4,64(a5)
	sw	zero,64(a5)
	ble	a1,zero,.L29
	li	a4,0
	li	a3,-14667776
	addi	a3,a3,64
	j	.L32
.L31:
	addi	a4,a4,1
	addi	a0,a0,4
	beq	a1,a4,.L29
.L32:
	lbu	a5,6(a3)
	andi	a5,a5,0xff
	beq	a5,zero,.L31
	lw	a5,0(a0)
	sw	a5,8(a3)
	lw	a5,0(a0)
	sw	a5,12(a3)
	j	.L31
.L29:
	ret
	.globl	scream
scream:
	addi	sp,sp,-16
	sw	ra,12(sp)
	lui	a5,%hi(samples_n)
	lw	a1,%lo(samples_n)(a5)
	lui	a0,%hi(samples)
	addi	a0,a0,%lo(samples)
	call	audio_playback_mono
	lw	ra,12(sp)
	addi	sp,sp,16
	jr	ra
	.align	2
	.globl	moo
moo:
	addi	sp,sp,-16
	sw	ra,12(sp)
	lui	a5,%hi(cowsamples_n)
	lw	a1,%lo(cowsamples_n)(a5)
	lui	a0,%hi(cowsamples)
	addi	a0,a0,%lo(cowsamples)
	call	audio_playback_mono
	lw	ra,12(sp)
	addi	sp,sp,16
	jr	ra
	
